#[test_only]
module protocol::market_t {
    use protocol::app::AdminCap;
    use protocol::app::ProtocolApp;
    use protocol::market::Market;
    use sui::clock::Clock;
    use sui::sui::SUI;

    use test_coin::eth::ETH;
    use test_coin::usdc::USDC;
    use test_coin::usdt::USDT;

    use sui::test_scenario::Scenario;
    use protocol::constants::usdc_interest_model_params;
    use protocol::constants;
    use protocol::constants::eth_interest_model_params;
    use protocol::constants::usdt_interest_model_params;
    use protocol::constants::sui_interest_model_params;
    use protocol::coin_decimals_registry_t::coin_decimals_registry_init;
    use protocol::coin_decimals_registry::CoinDecimalsRegistry;
    use protocol::constants::InterestModelParams;
    use protocol::obligation::ObligationOwnerCap;
    use protocol::market::lending_default_emode_group;
    use x_oracle::x_oracle::XOracle;
    use protocol::oracle_t;

    public struct MainMarket {}

    public fun default_decimal_places(): u8 { 9 }
    public fun default_eth_decimal_places(): u8 { 8 }
    public fun default_stable_decimal_places(): u8 { 6 }

    const LENDER: address = @0xAA;

    public fun setup_sample_market<T>(
        admin_cap: &AdminCap,
        app: &mut ProtocolApp,
        market: &mut Market<T>,
        x_oracle: &mut XOracle,
        clock: &Clock,
        scenario: &mut Scenario,
    ): CoinDecimalsRegistry {

        let mut coin_decimals_registry = coin_decimals_registry_init(scenario);

        protocol::emode_admin::onboard_new_emode_group<T>(
            admin_cap, 
            app, 
            market,
            0, 
            clock,
            scenario.ctx(),
        );

        let usdc_interest_params = usdc_interest_model_params();
        onboard_asset<T, USDC>(
            admin_cap, 
            app, 
            market, 
            &usdc_interest_params, 
            clock, 
            scenario.ctx(),
            7000,
            7000
        );

        coin_decimals_registry.register_decimals_t<USDC>(6);
        x_oracle.update_price<USDC>(clock, oracle_t::calc_scaled_price(1, 0));

        onboard_asset<T, SUI>(
            admin_cap, 
            app, 
            market, 
            &sui_interest_model_params(), 
            clock, 
            scenario.ctx(),
            7000,
            7000
        );
        coin_decimals_registry.register_decimals_t<SUI>(9);
        x_oracle.update_price<SUI>(clock, oracle_t::calc_scaled_price(1, 0));

        let eth_interest_params = eth_interest_model_params();
        onboard_asset<T, ETH>(
            admin_cap, 
            app, 
            market, 
            &eth_interest_params, 
            clock, 
            scenario.ctx(),
            7000,
            7000
        );
        coin_decimals_registry.register_decimals_t<ETH>(8);
        x_oracle.update_price<ETH>(clock, oracle_t::calc_scaled_price(1, 0));

        let usdt_interest_params = usdt_interest_model_params();
        onboard_asset<T, USDT>(
            admin_cap, 
            app, 
            market, 
            &usdt_interest_params, 
            clock, 
            scenario.ctx(),
            6000,
            6000
        );
        coin_decimals_registry.register_decimals_t<USDT>(6);
        x_oracle.update_price<USDT>(clock, oracle_t::calc_scaled_price(1, 0));

        // setup initial deposits

        scenario.next_tx(LENDER);
        protocol::enter_market::enter_market(app, market, scenario.ctx());

        scenario.next_tx(LENDER);
        let lender_obligation = scenario.take_from_sender<ObligationOwnerCap>();

        let usdc_coin = sui::coin::mint_for_testing<USDC>( 10u64.pow(default_decimal_places() + 4), scenario.ctx());
        let usdt_coin = sui::coin::mint_for_testing<USDT>( 10u64.pow(default_decimal_places() + 4), scenario.ctx());
        let eth_coin = sui::coin::mint_for_testing<ETH>( 10u64.pow(default_decimal_places() + 2), scenario.ctx());
        let sui_coin = sui::coin::mint_for_testing<SUI>( 10u64.pow(default_decimal_places() + 2), scenario.ctx());

        protocol::deposit::deposit<T, USDC>(app, market, &lender_obligation, usdc_coin, clock, scenario.ctx());
        protocol::deposit::deposit<T, USDT>(app, market, &lender_obligation, usdt_coin, clock, scenario.ctx());
        protocol::deposit::deposit<T, ETH>(app, market, &lender_obligation, eth_coin, clock, scenario.ctx());
        protocol::deposit::deposit<T, SUI>(app, market, &lender_obligation, sui_coin, clock, scenario.ctx());
        scenario.return_to_sender(lender_obligation);

        coin_decimals_registry
    }

    public fun increase_deposit<MarketType, CoinType>(
        app: &mut ProtocolApp,
        market: &mut Market<MarketType>,
        _coin_decimals_registry: &CoinDecimalsRegistry,
        _x_oracle: &XOracle,
        clock: &Clock,
        scenario: &mut Scenario,
        amount: u64,
    ) {
        scenario.next_tx(LENDER);
        let lender_obligation = scenario.take_from_sender<ObligationOwnerCap>();
        let coins = sui::coin::mint_for_testing<CoinType>(amount, scenario.ctx());
        protocol::deposit::deposit<MarketType, CoinType>(app, market, &lender_obligation, coins, clock, scenario.ctx());
        scenario.return_to_sender(lender_obligation);
    }

    fun onboard_asset<T, CoinType>(
        admin_cap: &AdminCap,
        app: &ProtocolApp,
        market: &mut Market<T>,
        params: &InterestModelParams<CoinType>,
        clock: &Clock,
        ctx: &mut TxContext,
        collateral_factor: u64,
        liquidation_factor: u64
    ) {
        let interest_model = protocol::asset_admin::create_interest_model_test(
            admin_cap,
            constants::base_rate_per_sec(params),
            constants::borrow_rate_on_mid_kink(params),
            constants::mid_kink(params),
            constants::borrow_rate_on_high_kink(params),
            constants::high_kink(params),
            constants::max_borrow_rate(params),
        );

       let liquidation_fee_rate: u64 = 100;
        constants::borrow_weight_rate();

        let asset_config = protocol::asset_admin::create_market_asset_config(
            admin_cap,
            app,
            constants::min_borrow_amount(), 
            constants::max_borrow_amount(),
            1000000000000000000,
            constants::repay_fee_rate(),
            liquidation_fee_rate,
        );

        protocol::asset_admin::onboard_new_asset<T, CoinType>(
            admin_cap,
            app, 
            market, 
            interest_model, 
            asset_config, 
            clock, 
            ctx
        );


        let deposit_limiter = protocol::emode_admin::create_limiter(
            admin_cap,
            app,
            2u64.pow(63),
            10000000,
            10000000
        );

        let borrow_limiter = protocol::emode_admin::create_limiter(
            admin_cap,
            app,
            2u64.pow(63),
            10000000,
            10000000
        );

        let liquidation_incentive: u64 = 500;

        // default emode group has been created
        let emode_group = protocol::emode_admin::create_emode_params_test(
            admin_cap,

            collateral_factor,
            liquidation_factor,
            liquidation_incentive,

            constants::max_borrow_amount(),
            constants::borrow_weight_rate(),
            constants::flash_loan_fee_rate(),

            deposit_limiter,
            borrow_limiter,
        );


        protocol::emode_admin::onboard_asset_to_emode_group<T, CoinType>(
            admin_cap,
            app,
            market,
            lending_default_emode_group(),
            emode_group,
            ctx,
        );
   }
}

